package com.company.platform.commerce.application;
import com.company.platform.commerce.domain.events.CommerceEvent;import com.company.platform.commerce.domain.product.*;import com.company.platform.commerce.infrastructure.*;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ProductApplicationService { private final ProductRepository products;private final SellableProductRepository sellables;private final TenantContextProvider tenant;private final KafkaCommerceEventPublisher events;public ProductApplicationService(ProductRepository products,SellableProductRepository sellables,TenantContextProvider tenant,KafkaCommerceEventPublisher events){this.products=products;this.sellables=sellables;this.tenant=tenant;this.events=events;}private UUID t(){return tenant.currentTenantId();}
 @Transactional public Product create(String sku,String name,String description){UUID tenantId=t();if(products.findByTenantIdAndSku(tenantId,sku).isPresent())throw new IllegalStateException("SKU_ALREADY_EXISTS");var p=products.save(Product.create(tenantId,new SKU(sku),new ProductName(name),description));sellables.save(SellableProduct.rehydrate(p.id(),tenantId,p.id(),UUID.randomUUID(),SellableProductStatus.DISABLED,p.createdAt(),p.updatedAt()));events.publish(new CommerceEvent(UUID.randomUUID(),"PRODUCT_CREATED",p.id(),p.tenantId(),Instant.now(),Map.of("productId",p.id(),"sku",p.sku().value())));return p;}
 public Product get(UUID id){return products.findByTenantIdAndId(t(),id).orElseThrow(()->new NoSuchElementException("PRODUCT_NOT_FOUND"));}public List<Product> search(String q,ProductStatus status){return products.search(t(),q,status);}
 @Transactional public Product update(UUID id,String name,String description){var p=get(id);p.update(new ProductName(name),description);return products.save(p);}
 @Transactional public Product changeStatus(UUID id,ProductStatus status){var p=get(id);var sellable=sellables.findByTenantIdAndId(t(),id).orElseThrow(()->new NoSuchElementException("PRODUCT_NOT_FOUND"));if(status==ProductStatus.ACTIVE){p.activate();sellable.enable();}else if(status==ProductStatus.INACTIVE){p.deactivate();sellable.disable();}sellables.save(sellable);return products.save(p);}
}
